const inputJson = $input.first().json;

let raw =
  inputJson.output ||
  inputJson.text ||
  '';

// 1. Buscar la URL primero en intermediateSteps (fuente confiable, cruda)
let imagenUrl = null;
const pasos = inputJson.intermediateSteps || [];

for (const paso of pasos) {
  const obs = (paso.observation || '').toString();
  const match = obs.match(/https:\/\/(quickchart\.io\/chart|hzgoxdpvlvzxzwoefeui\.supabase\.co\/storage)[^\s\)\]"']+/);
  if (match) {
    imagenUrl = match[0];
    break; // toma la primera imagen encontrada
  }
}

// 2. Si no la encontró ahí (fallback), buscar en el texto final por si el LLM sí la copió
if (!imagenUrl) {
  const matchFinal = raw.match(/https:\/\/(quickchart\.io\/chart|hzgoxdpvlvzxzwoefeui\.supabase\.co\/storage)[^\s\)\]"']+/);
  if (matchFinal) imagenUrl = matchFinal[0];
}

// 3. Limpiar el texto de respuesta: quitar markdown, URLs sueltas y frases redundantes
let respuesta = raw
  .replace(/\[Ver gráfico\]\([^\)]+\)/gi, '')
  .replace(/\[[^\]]*\]\(https:\/\/(quickchart\.io\/chart|hzgoxdpvlvzxzwoefeui\.supabase\.co\/storage)[^\)]+\)/gi, '')
  .replace(/https:\/\/(quickchart\.io\/chart|hzgoxdpvlvzxzwoefeui\.supabase\.co\/storage)[^\s\)\]"']+/g, '')
  .replace(/Aquí tienes el gráfico comparativo:/gi, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (!respuesta || respuesta.length < 5) {
  respuesta = 'Lo siento, no pude generar una respuesta en este momento. ¿Podrías intentarlo de nuevo?';
}

return [{
  json: {
    respuesta:    respuesta,
    imagen_url:   imagenUrl,
    tiene_imagen: imagenUrl !== null,
    pregunta:     $('Foxy Contexto SQL').first().json.pregunta,
    sessionId:    $('Foxy Contexto SQL').first().json.sessionId,
    output:       imagenUrl ? (respuesta + '\n' + imagenUrl) : respuesta
  }
}];

const respuesta = $input.first().json.respuesta || '';
const sessionId = $input.first().json.sessionId || '';
const esConfirmacion = $input.first().json.es_confirmacion || false;

const staticData = $getWorkflowStaticData('global');

// Solo guarda si NO fue una confirmación ya ejecutada
// Así evitas que una respuesta vieja siga viva como "propuesta pendiente"
if (!esConfirmacion) {
  staticData[sessionId] = {
    ultimaRespuesta: respuesta.substring(0, 1000),
    timestamp: new Date().toISOString()
  };
} else {
  // Si fue confirmación, limpia para que no quede propuesta vieja
  delete staticData[sessionId];
}

return $input.all();

const respuesta = ($input.first().json.text || '').toLowerCase().trim();
const intencionClassifier = respuesta.includes('sql') ? 'sql' : 'conversacional';

const contexto = $('Foxy Contexto SQL').first().json;
const pregunta = (contexto.pregunta || '').toLowerCase().trim();

// ── REGLA DE INDICADORES — prioridad máxima, corre antes que todo ──
const INDICADORES_SQL = [
  'deserción', 'desercion', 'desertores', 'desertor',
  'matrícula', 'matricula', 'matriculados', 'matriculadas',
  'graduados', 'graduadas', 'graduación', 'graduacion',
  'ausentismo', 'ausentes', 'ausente',
  'retención', 'retencion',
  'primiparos', 'primíparos', 'cohorte',
  'programas activos', 'oferta activa', 'oferta académica', 'oferta academica',
  'estudiantes nuevos', 'estudiantes totales', 'estudiantes continuos',
  'tasa de', 'cuántos estudiantes', 'cuantos estudiantes',
  'datos ya', 'cifras ya', 'dime ya', 'muéstrame ya', 'muestrame ya',
  'no me hagas esperar', 'rápido', 'rapido', 'apurate', 'apúrate',
  'todos los niveles', 'sin filtro', 'todos los programas'
];

const tieneIndicador = INDICADORES_SQL.some(ind => pregunta.includes(ind));
if (tieneIndicador) {
  return [{
    json: {
      ...contexto,
      intencion: 'sql',
      es_confirmacion: false
    }
  }];
}

// ── Patrones que indican pregunta contextual (NO requiere SQL nuevo) ──
const patronesContextuales = [
  /\bdiferencia\b.*\bporcentual\b/i,
  /\bcuál es la diferencia\b/i,
  /\bcómo se compara\b/i,
  /\by eso\b/i,
  /\by qué significa\b/i,
  /\bes bueno o malo\b/i,
  /\bqué opinas\b/i,
  /\bpor qué (?!no|no hay|no se)\b/i,
  /\bcómo se explica\b/i,
  /\ba qué se debe\b/i,
  /\bqué pasó\b/i,
  /\by entonces\b/i,
  /\bcontinuando\b/i,
  /\bsiguiendo\b/i,
  /\bprofundiz[áa]\b/i,
  /\bexplic[áa]me\b/i,
  /\bdetall[áa]\b/i,
  /\by la más\b/i,
  /\by el más\b/i,
  /\by cuál es (?:el|la) más\b/i,
  /\by (?:el|la) (?:otro|otra|anterior|siguiente)\b/i,
  /\by en (?:el|la) \w+ año\b/i,
  /\by (?:eso|esto|ese|esa|esos|esas)\b/i,
  /\by (?:cuál|cuáles)\b/i,
  /\bdel anterior\b/i,
  /\bdel año pasado\b/i,
  /\bdel mismo período\b/i,
  /\bes preocupante\b/i,
  /\bes bueno o malo\b/i,
  /\bes grave\b/i,
  /\bes normal\b/i,
  /\bes positivo o negativo\b/i,
  /\bqué tan grave\b/i,
  /\bcómo lo ves\b/i,
  /\bqué pensás\b/i,
  /\bqué opinión\b/i,
  /\bno me hagas esperar\b/i,
  /\bdate prisa\b/i,
  /\brápido\b/i,
  /\bapurate\b/i,
  /\bno tardes\b/i,
  /\bes urgente\b/i,
  /\bya mismo\b/i,
  /\bahora\b/i,
  /\bveloz\b/i,
  /\bno, (?:quiero|quisiera|prefiero)\b/i,
  /\bcambi[áa]lo\b/i,
  /\bcorregí\b/i,
  /\bno es (?:eso|así)\b/i,
  /\bme equivoqué\b/i,
  /\btodos los niveles\b/i,
  /\bsin filtro\b/i,
  /^datos\s+ya\b/i,
  /^cifras\s+ya\b/i,
];

const esPreguntaContextual = patronesContextuales.some(p => p.test(pregunta));

if (esPreguntaContextual) {
  return [{
    json: {
      ...contexto,
      intencion: 'conversacional',
      es_confirmacion: false
    }
  }];
}

const PATRON_CONFIRMACION = [
  'sí', 'si', 's', 'dale', 'claro', 'hazlo', 'ok', 'vale', 'perfecto',
  'está bien', 'procede', 'adelante', 'muéstramelo', 'hagámoslo',
  'por favor', 'correcto', 'exacto', 'genial', 'listo', 'bueno',
  'claro que sí', 'por supuesto', 'sí por favor', 'sí, por favor',
  'muéstrame', 'hacemos eso', 'sí, hazlo', 'sí claro',
  'de acuerdo', 'sí, adelante', 'veamos', 'vamos', 'va',
  'sí, veamos', 'sí, claro', 'sí, dale', 'sí, perfecto',
  'hagamoslo', 'va pues', 'eso', 'a ver', 'show me', 'yes', 'yep', 'y'
];

const esConfirmacion =
  pregunta.length <= 40 &&
  PATRON_CONFIRMACION.some(p =>
    pregunta === p ||
    pregunta === p + '.' ||
    pregunta === p + '!' ||
    pregunta.startsWith(p + ' ') ||
    pregunta.endsWith(' ' + p) ||
    pregunta === '¡' + p + '!'
  );

const patronAnalisisDirecto = /\b(análisis|analisis|estrategia|estrategias|estratégico|estrategico|recomendación|recomendacion|recomendaciones|factores|implicaciones|oportunidades|amenazas|fortalezas|debilidades)\b/i;
const esPedidoAnalisis = patronAnalisisDirecto.test(pregunta);

if (esPedidoAnalisis) {
  return [{
    json: {
      ...contexto,
      intencion: 'conversacional',
      es_confirmacion: false
    }
  }];
}

let forzarSql = false;
let ultimaRespuestaTieneOpciones = false;
let ultima = '';

try {
  const staticData = $getWorkflowStaticData('global');
  const sessionId = contexto.sessionId || '';
  if (staticData[sessionId] && staticData[sessionId].ultimaRespuesta) {
    ultima = staticData[sessionId].ultimaRespuesta.toLowerCase();
    const patronDatos = /\b(distribución|distribuir|evolución|evolucionado|tendencia|gráfico|graficar|visualizar|comparar|comparación|desglos|desglose|por año|por sede|por facultad|por programa|por modalidad|por centro|cuántos|cuántas|cifras|totales|ranking|top|dimensión)\b/i;
    const patronAnalisis = /\b(estrategias|factores|recomendaciones|cómo mejorar|cómo fortalecer|qué acciones|qué medidas|por qué crees|análisis cualitativo|análisis estratégico|interpretación|implicaciones|consecuencias|oportunidades|amenazas)\b/i;
    const patronOpciones = /(?:por|entre|en)\s+\w+(?:\s+\w+)*\s+(?:o|ó)\s+\w+/i;
    const tieneSignosInterrogacion = (ultima.match(/\?/g) || []).length >= 2;
    ultimaRespuestaTieneOpciones = patronOpciones.test(ultima) || tieneSignosInterrogacion;
    if (patronDatos.test(ultima) && !patronAnalisis.test(ultima)) forzarSql = true;
    if (patronAnalisis.test(ultima)) forzarSql = false;
  }
} catch(e) {
  forzarSql = true;
}

let intencion;
if (!esConfirmacion) {
  intencion = intencionClassifier;
} else if (ultimaRespuestaTieneOpciones && (ultima.match(/\?/g) || []).length >= 2) {
  intencion = 'conversacional';
} else if (forzarSql) {
  intencion = 'sql';
} else {
  intencion = 'conversacional';
}

return [{
  json: {
    ...contexto,
    intencion: intencion,
    es_confirmacion: esConfirmacion
  }
}];

const contexto = $('Foxy Contexto SQL').first().json;

let querySql = '';
try {
  querySql = $('Extraer Query').first()?.json?.query || '';
} catch(e) {
  querySql = '';
}

const sessionId  = (contexto.sessionId  || 'session_default').replace(/'/g, "''");
const userId     = (contexto.userId     || 'user_default').replace(/'/g, "''");
const pregunta   = (contexto.pregunta   || '').replace(/'/g, "''");
const queryClean = querySql.replace(/'/g, "''");
const totalFilas = $json.total_filas || 0;
const fueraAlcance = $json.fuera_alcance || false;

return [{
  json: {
    sessionId,
    userId,
    pregunta,
    querySql: queryClean,
    totalFilas,
    fueraAlcance
  }
}];

return [{
  json: {
    datos:           [],
    total_filas:     0,
    pregunta:        $json.pregunta,
    sessionId:       $json.sessionId,
    userId:          $json.userId,
    es_confirmacion: false,
    fuera_alcance:   false,
    es_conversacional: true
  }
}];

const extraerJson = $('Extraer Query').first().json;

const firstInput = $input.first().json;
const esFueraAlcance = firstInput.fuera_alcance === true && firstInput.query === null;

if (esFueraAlcance) {
  return [{
    json: {
      datos:           [],
      total_filas:     0,
      pregunta:        extraerJson.pregunta,
      sessionId:       extraerJson.sessionId,
      es_confirmacion: extraerJson.es_confirmacion || false,
      fuera_alcance:   true
    }
  }];
}

const items = $input.all().map(i => i.json);
const limitado = items.slice(0, 50);

return [{
  json: {
    datos:           limitado,
    total_filas:     items.length,
    pregunta:        extraerJson.pregunta,
    sessionId:       extraerJson.sessionId,
    es_confirmacion: extraerJson.es_confirmacion || false,
    fuera_alcance:   false
  }
}];

