// Si es fuera de alcance, pasar directo sin validar SQL
if ($json.fuera_alcance === true) {
  return [{ json: $json }];
}

const query = $json.query?.toString() || '';
const queryUpper = query.toUpperCase();

// Normalizar: quitar tildes para comparación robusta
const normalizar = str => str
  .toUpperCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '');

const queryNorm = normalizar(query);

// Blacklist de operaciones prohibidas
const blacklist = [
  'INSERT','UPDATE','DELETE','DROP','TRUNCATE',
  'ALTER','CREATE','EXEC','EXECUTE','XP_','SP_',
  'SHUTDOWN','OPENROWSET','BULK','GRANT','REVOKE',
  'DENY','BACKUP','RESTORE','DBCC'
];
const bloqueado = blacklist.find(w => queryNorm.includes(w));
if (bloqueado) throw new Error(`Operación no permitida: ${bloqueado}`);

// Validar filtro obligatorio de Rectoría — con excepción para Oferta_Activa
// Se normaliza para cubrir: Rectoría, RECTORÍA, RECTORIA, Rectoria
const esOfertaActiva = queryNorm.includes('OFERTA_ACTIVA');
const tieneRectoria  = queryNorm.includes('RECTORIA');
if (!tieneRectoria && !esOfertaActiva) {
  throw new Error('El query no incluye el filtro obligatorio de Rectoría.');
}

// Prohibir acceso a tablas del sistema
const sistemaTables = [
  'SYS.','SYSOBJECTS','SYSCOLUMNS','INFORMATION_SCHEMA',
  'SYS.TABLES','SYS.COLUMNS','SYS.DATABASES',
  'MASTER','MSDB','TEMPDB','MODEL'
];
const tablaBloqueada = sistemaTables.find(t => queryNorm.includes(t));
if (tablaBloqueada) throw new Error(`Acceso no permitido: ${tablaBloqueada}`);

// Solo permitir las 5 tablas de Foxy
const tablasPermitidas = [
  'POBLACION_ESTUDIANTIL',
  'CARACTERIZACION_ESTUDIANTES',
  'INDICADORES_PROYECCIONES',
  'PROYECCION_ESTUDIANTES',
  'OFERTA_ACTIVA'
];
const tieneTablaPermitida = tablasPermitidas.some(t => queryNorm.includes(t));
if (!tieneTablaPermitida) throw new Error('El query no referencia ninguna tabla autorizada de Foxy.');

// Prohibir comentarios solo si vienen ANTES de un SELECT (posible inyección)
// Comentarios dentro del query son válidos
const sinStrings = query.replace(/'[^']*'/g, "''");
const inyeccionComentario = /^\s*(--|\/)/.test(sinStrings);
if (inyeccionComentario) {
  throw new Error('El query comienza con comentario — posible inyección.');
}

return [{ json: $json }];

const item = $('ejecutar_query').first().json;
const output = item.output || item.text || item.response || JSON.stringify(item);

const esConfirmacion    = $('Code in JavaScript1').first().json.es_confirmacion || false;
const preguntaOriginal  = $('Code in JavaScript1').first().json.pregunta_original
                          || $('Code in JavaScript1').first().json.pregunta
                          || $('Foxy Contexto SQL').first().json.pregunta;

if (output.includes('FUERA_DE_ALCANCE')) {
  return [{
    json: {
      query:             null,
      fuera_alcance:     true,
      es_confirmacion:   esConfirmacion,
      pregunta:          preguntaOriginal,
      sessionId:         $('Foxy Contexto SQL').first().json.sessionId,
      userId:            $('Foxy Contexto SQL').first().json.userId
    }
  }];
}

let query = null;
const sqlBlock = output.match(/```sql\s*([\s\S]*?)```/i);
if (sqlBlock) {
  query = sqlBlock[1].trim();
} else {
  const selectMatch = output.match(/(SELECT[\s\S]+)/i);
  if (selectMatch) {
    query = selectMatch[1].split('```')[0].trim();
  }
}

if (query) {
  query = query.replace(/\\n/g, '\n').trim();
}

if (!query || !query.toUpperCase().includes('SELECT')) {
  return [{
    json: {
      query:             null,
      fuera_alcance:     true,
      respuesta_directa: output,
      es_confirmacion:   esConfirmacion,
      pregunta:          preguntaOriginal,
      sessionId:         $('Foxy Contexto SQL').first().json.sessionId,
      userId:            $('Foxy Contexto SQL').first().json.userId
    }
  }];
}

return [{
  json: {
    query:             query,
    fuera_alcance:     false,
    es_confirmacion:   esConfirmacion,
    pregunta:          preguntaOriginal,
    sessionId:         $('Foxy Contexto SQL').first().json.sessionId,
    userId:            $('Foxy Contexto SQL').first().json.userId
  }
}];

const contexto = $input.first().json;
const preguntaLower = contexto.pregunta.toLowerCase();
const sessionId = contexto.sessionId || '';

// Detectar referencias contextuales
const esReferencial = [
  'eso mismo', 'lo mismo', 'igual pero', 'pero del', 'pero en',
  'pero solo', 'pero para', 'ahora de', 'ahora en', 'y del',
  'y de', 'y en', 'mismo pero'
].some(p => preguntaLower.includes(p));

// Recuperar staticData una sola vez
let ultimaPropuesta = '';
try {
  const staticData = $getWorkflowStaticData('global');
  const entrada = staticData[sessionId];
  if (entrada?.ultimaRespuesta && entrada?.timestamp) {
    const edad = Date.now() - new Date(entrada.timestamp).getTime();
    const DIEZ_MIN = 10 * 60 * 1000;
    if (edad <= DIEZ_MIN) {
      ultimaPropuesta = entrada.ultimaRespuesta;
    } else {
      delete staticData[sessionId];
    }
  }
} catch(e) {}

// Caso 1: Pregunta referencial (eso mismo pero del 2025, etc.)
if (esReferencial && ultimaPropuesta) {
  const instruccion = `[PREGUNTA REFERENCIAL]
El usuario preguntó: "${contexto.pregunta}"
Esto hace referencia a la respuesta anterior del asistente:
"${ultimaPropuesta}"
INSTRUCCIÓN: Genera el SQL equivalente pero aplicando el nuevo filtro que pide el usuario.
Mantén las mismas dimensiones y métricas de la consulta anterior.
Aplica filtro Rectoría = 'Bogotá'.`;

  return [{
    json: {
      ...contexto,
      pregunta: instruccion,
      pregunta_original: contexto.pregunta
    }
  }];
}

// Caso 2: No es confirmación ni referencial — pasar sin modificar
if (!contexto.es_confirmacion) {
  return [{ json: contexto }];
}

// Caso 3: Es confirmación pero intención conversacional — dejar a Foxy Analista
if (contexto.intencion === 'conversacional') {
  return [{ json: contexto }];
}

// Caso 4: Confirmación con intención SQL
const instruccion = ultimaPropuesta
  ? `[CONFIRMACIÓN DE PROPUESTA]
El usuario respondió "${contexto.pregunta}" confirmando esta propuesta del asistente:
"${ultimaPropuesta}"
INSTRUCCIÓN OBLIGATORIA:
1. La propuesta confirmada está entre comillas arriba
2. Genera el SQL EXACTO para cumplir ESA propuesta — NO la consulta anterior
3. Si habla de "evolución", "tendencia", "años" → GROUP BY Año ORDER BY Año ASC
4. Si habla de "distribución", "por facultad", "por programa" → GROUP BY esa dimensión
5. Aplica filtro Rectoría = 'Bogotá'
6. NUNCA respondas FUERA_DE_ALCANCE`
  : `[CONFIRMACIÓN DE PROPUESTA]
El usuario respondió "${contexto.pregunta}".
Busca en tu historial la última sugerencia que hiciste y ejecútala.
NUNCA repitas la consulta anterior. Genera la NUEVA consulta.`;

return [{
  json: {
    ...contexto,
    pregunta: instruccion,
    pregunta_original: contexto.pregunta
  }
}];
